-- 04F bundle — apply ONLY on isolated DB after clone from existing app schema.
-- Order: base SalesRequests -> 04A columns/timeline -> 04D outbox -> 04E columns.
-- Verified host before apply: localhost / ::1 port 5432 — Database: qalaat_04f_sales_verify

-- ===== SCHEMA_REQUIRED (base) =====
CREATE TABLE IF NOT EXISTS "SalesRequests" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CustomerName" character varying(120) NOT NULL,
  "CustomerPhone" character varying(30) NULL,
  "SourceType" smallint NOT NULL,
  "OriginalExternalId" character varying(100) NULL,
  "Status" smallint NOT NULL,
  "TargetEmployeeId" integer NULL,
  "BranchId" integer NOT NULL,
  "ProvinceId" integer NULL,
  "ExistingCustomerId" integer NULL,
  "CreatedByUserId" integer NULL,
  "ExceptionHoldStatus" smallint NULL,
  "RejectReason" character varying(500) NULL,
  "IsDeleted" boolean NOT NULL DEFAULT false,
  "ConcurrencyStamp" integer NOT NULL DEFAULT 0,
  "CreatedAt" timestamp with time zone NULL,
  "CreatedBy" integer NOT NULL DEFAULT 0,
  "LastUpdatedAt" timestamp with time zone NULL,
  "LastUpdatedBy" integer NOT NULL DEFAULT 0,
  CONSTRAINT "FK_SalesRequests_Branches_BranchId"
    FOREIGN KEY ("BranchId") REFERENCES "Branches" ("Id") ON DELETE RESTRICT,
  CONSTRAINT "FK_SalesRequests_Provinces_ProvinceId"
    FOREIGN KEY ("ProvinceId") REFERENCES "Provinces" ("Id") ON DELETE RESTRICT,
  CONSTRAINT "FK_SalesRequests_Customers_ExistingCustomerId"
    FOREIGN KEY ("ExistingCustomerId") REFERENCES "Customers" ("Id") ON DELETE SET NULL,
  CONSTRAINT "FK_SalesRequests_Users_TargetEmployeeId"
    FOREIGN KEY ("TargetEmployeeId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
  CONSTRAINT "FK_SalesRequests_Users_CreatedByUserId"
    FOREIGN KEY ("CreatedByUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS "IX_SalesRequests_BranchId_Status_TargetEmployeeId"
  ON "SalesRequests" ("BranchId", "Status", "TargetEmployeeId");
CREATE INDEX IF NOT EXISTS "IX_SalesRequests_CustomerPhone"
  ON "SalesRequests" ("CustomerPhone");
CREATE INDEX IF NOT EXISTS "IX_SalesRequests_CustomerName"
  ON "SalesRequests" ("CustomerName");
CREATE INDEX IF NOT EXISTS "IX_SalesRequests_OriginalExternalId"
  ON "SalesRequests" ("OriginalExternalId");

-- ===== 04A =====
ALTER TABLE "SalesRequests"
  ADD COLUMN IF NOT EXISTS "LinkedOrderId" integer NULL,
  ADD COLUMN IF NOT EXISTS "LastStatusNote" character varying(500) NULL,
  ADD COLUMN IF NOT EXISTS "ViewedAtUtc" timestamp with time zone NULL,
  ADD COLUMN IF NOT EXISTS "StatusChangedAtUtc" timestamp with time zone NULL,
  ADD COLUMN IF NOT EXISTS "ConcurrencyStamp" integer NOT NULL DEFAULT 0;

ALTER TABLE "SalesRequests"
  DROP CONSTRAINT IF EXISTS "FK_SalesRequests_Orders_LinkedOrderId";

ALTER TABLE "SalesRequests"
  ADD CONSTRAINT "FK_SalesRequests_Orders_LinkedOrderId"
  FOREIGN KEY ("LinkedOrderId") REFERENCES "Orders" ("Id") ON DELETE RESTRICT;

CREATE UNIQUE INDEX IF NOT EXISTS "IX_SalesRequests_LinkedOrderId"
  ON "SalesRequests" ("LinkedOrderId")
  WHERE "LinkedOrderId" IS NOT NULL;

CREATE INDEX IF NOT EXISTS "IX_SalesRequests_TargetEmployeeId"
  ON "SalesRequests" ("TargetEmployeeId");

CREATE TABLE IF NOT EXISTS "SalesRequestTimelineEntries" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "SalesRequestId" integer NOT NULL,
  "EventType" smallint NOT NULL,
  "ActorUserId" integer NOT NULL,
  "OccurredAtUtc" timestamp with time zone NOT NULL,
  "PreviousStatus" smallint NULL,
  "NewStatus" smallint NULL,
  "PreviousEmployeeId" integer NULL,
  "NewEmployeeId" integer NULL,
  "Reason" character varying(500) NULL,
  "OperationId" uuid NOT NULL,
  CONSTRAINT "FK_SalesRequestTimelineEntries_SalesRequests_SalesRequestId"
    FOREIGN KEY ("SalesRequestId") REFERENCES "SalesRequests" ("Id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IX_SalesRequestTimelineEntries_SalesRequestId_OccurredAtUtc"
  ON "SalesRequestTimelineEntries" ("SalesRequestId", "OccurredAtUtc");
CREATE INDEX IF NOT EXISTS "IX_SalesRequestTimelineEntries_OperationId"
  ON "SalesRequestTimelineEntries" ("OperationId");

-- ===== 04D =====
CREATE TABLE IF NOT EXISTS "SalesRequestChangeOutbox" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "EventId" uuid NOT NULL,
  "RequestId" integer NOT NULL,
  "Revision" integer NOT NULL,
  "OccurredAtUtc" timestamp with time zone NOT NULL,
  "ChangeType" character varying(32) NOT NULL,
  "BranchId" integer NOT NULL,
  "TargetEmployeeId" integer NULL,
  "PreviousTargetEmployeeId" integer NULL,
  "PublishedAtUtc" timestamp with time zone NULL,
  "RetryCount" integer NOT NULL DEFAULT 0,
  "LastAttemptAtUtc" timestamp with time zone NULL,
  "LastError" character varying(200) NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_SalesRequestChangeOutbox_EventId"
  ON "SalesRequestChangeOutbox" ("EventId");

CREATE INDEX IF NOT EXISTS "IX_SalesRequestChangeOutbox_PublishedAtUtc_Id"
  ON "SalesRequestChangeOutbox" ("PublishedAtUtc", "Id");

CREATE INDEX IF NOT EXISTS "IX_SalesRequestChangeOutbox_RequestId_Revision"
  ON "SalesRequestChangeOutbox" ("RequestId", "Revision");

-- ===== 04E =====
ALTER TABLE "SalesRequests"
  ADD COLUMN IF NOT EXISTS "ExceptionDecidedByUserId" integer NULL,
  ADD COLUMN IF NOT EXISTS "ExceptionDecidedAtUtc" timestamp with time zone NULL,
  ADD COLUMN IF NOT EXISTS "ExceptionConsumedAtUtc" timestamp with time zone NULL,
  ADD COLUMN IF NOT EXISTS "DeletedAtUtc" timestamp with time zone NULL,
  ADD COLUMN IF NOT EXISTS "DeletedByUserId" integer NULL,
  ADD COLUMN IF NOT EXISTS "DeleteReason" character varying(500) NULL;

CREATE INDEX IF NOT EXISTS "IX_SalesRequests_BranchId_DeletedAtUtc"
  ON "SalesRequests" ("BranchId", "DeletedAtUtc")
  WHERE "IsDeleted" = true;

CREATE INDEX IF NOT EXISTS "IX_SalesRequests_BranchId_ExceptionHoldStatus"
  ON "SalesRequests" ("BranchId", "ExceptionHoldStatus")
  WHERE "ExceptionHoldStatus" IS NOT NULL;
